using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace GearLab {public static class MaterialLibrary {
 const string Petg="https://storage.googleapis.com/prusa3d-content-prod-14e8-wordpress-forum-prod/2024/10/f413a264-petg_prusament_tds_2021_10_en.pdf";
 const string Pla="https://store.bblcdn.eu/s8/default/073e722a4aa44f7cbfdc419d597475cc/Bambu_PLA_Basic_Technical_Data_Sheet.pdf";
 const string Aluminium="https://online.kaiseraluminum.com/depot/PublicProductInformation/Document/1006/Kaiser_Aluminum_Shapes_Soft_Alloy.pdf";
 static TrainMaterial M(string name,string kind,double density){return new TrainMaterial{Name=name,Kind=kind,Density=density,LayerFactor=kind=="FDM"?.5:1,Source="Плотность: ориентировочное справочное значение для массы; замените по TDS своей марки. Прочностные свойства не заданы. LayerFactor=0,5 для FDM — пользовательское допущение задания, не паспорт."};}
 public static List<TrainMaterial> Defaults(){var list=new List<TrainMaterial>{M("PETG","FDM",1270),M("PLA","FDM",1240),M("ABS","FDM",1050),M("ASA","FDM",1070),M("PA12","FDM",1010),M("PC","FDM",1200),M("POM","Polymer",1420),M("Сталь 45","Metal",7850),M("Нержавеющая сталь","Metal",7900),M("Алюминий 6061-T6","Metal",2700),M("Бронза","Metal",8800)};var petg=list[0];petg.Yield=47;petg.Elastic=1500;petg.Source="Ориентир: Prusament PETG, горизонтальные образцы, 100% заполнение. Плотность 1270 кг/м³; текучесть 47 МПа; E=1500 МПа. Иные марки и режимы не подтверждены. LayerFactor=0,5 — допущение пользователя. "+Petg;var pla=list[1];pla.Tensile=35;pla.Elastic=2580;pla.MaxTemp=57;pla.Source="Ориентир: Bambu PLA Basic TDS V3.0, XY, 100% заполнение, отжиг/сушка 55 °C 8 ч. Плотность 1240 кг/м³, прочность 35 МПа, E=2580 МПа, Vicat=57 °C. Предел текучести и срез не заданы. LayerFactor=0,5 — допущение пользователя. "+Pla;var al=list[9];al.Yield=276;al.Tensile=310;al.Elastic=68300;al.Shear=207;al.Source="Ориентир Kaiser: экструдированный 6061-T6; плотность 2700 кг/м³, текучесть 276, прочность 310, срез 207, E=68300 МПа. Типичные данные, не гарантии для другой термообработки. "+Aluminium;return list;}
 public static TrainMaterial Clone(TrainMaterial m){return CADDocument.Serializer().Deserialize<TrainMaterial>(CADDocument.Serializer().Serialize(m));}
 public static void Validate(TrainMaterial m){if(m==null||string.IsNullOrWhiteSpace(m.Name)||m.Name.Length>100||!new[]{"FDM","Metal","Polymer"}.Contains(m.Kind)||(string.IsNullOrWhiteSpace(m.Source)||m.Source.Length>4000))throw new Exception("Материал: задайте имя, вид FDM/Metal/Polymer и источник данных.");if(!MechanismCad.Finite(m.Density)||m.Density<100||m.Density>25000||!MechanismCad.Finite(m.LayerFactor)||m.LayerFactor<0||m.LayerFactor>1)throw new Exception(m.Name+": плотность 100–25000 кг/м³; доля прочности слоёв 0–1.");foreach(double? v in new[]{m.Yield,m.Tensile,m.Elastic,m.Shear})if(v.HasValue&&(!MechanismCad.Finite(v.Value)||v<=0||v>10000000))throw new Exception(m.Name+": механические свойства должны быть положительными либо пустыми (не определено).");if(m.Friction.HasValue&&(!MechanismCad.Finite(m.Friction.Value)||m.Friction<0||m.Friction>2)||m.MaxTemp.HasValue&&(!MechanismCad.Finite(m.MaxTemp.Value)||m.MaxTemp< -100||m.MaxTemp>2000))throw new Exception(m.Name+": недопустимые трение или температура.");}
 public static List<TrainMaterial> Resolve(TransmissionTrain t){var values=Defaults();if(t.Materials!=null){if(t.Materials.Custom==null||t.Materials.Parts==null||t.Materials.Roles==null||t.Materials.Custom.Count>100)throw new Exception("Некорректный справочник материалов проекта.");var seen=new HashSet<string>();foreach(var m in t.Materials.Custom){Validate(m);if(!seen.Add(m.Name))throw new Exception("Повтор имени материала: "+m.Name);values.RemoveAll(x=>x.Name==m.Name);values.Add(m);}foreach(string name in t.Materials.Roles.Values.Concat(t.Materials.Parts.Values))if(!values.Any(m=>m.Name==name))throw new Exception("Неизвестный материал: "+name);}return values;}
 public static string Role(string role){return role=="spring"||role=="friction"||role=="pin"||role=="roller"?"shaft":role=="fixed"?"housing":role;}
 public static TrainMaterial For(TransmissionTrain t,CadPart p){if(t.Materials==null)return null;string name;var all=Resolve(t);if(p.Role=="friction"&&t.Overload!=null&&!string.IsNullOrWhiteSpace(t.Overload.FrictionMaterial))return all.First(m=>m.Name==t.Overload.FrictionMaterial);if(t.Materials.Parts.TryGetValue(p.Id,out name)||t.Materials.Roles.TryGetValue(Role(p.Role),out name))return all.First(m=>m.Name==name);return null;}
 public static void Assign(TransmissionTrain t,TrainSolution s){Resolve(t);s.Mass=0;foreach(var p in s.Scene.Model.Parts){if(p.Reference)continue;var m=For(t,p);double density=m==null?(p.Role=="housing"?1250:7850):m.Density;p.MaterialName=m==null?null:m.Name;p.MaterialKind=m==null?null:m.Kind;p.MaterialDensity=density;p.MaterialSource=m==null?"Прежняя плотность по роли":m.Source;s.Mass+=p.Volume()*1e-9*density;if(PrintExport.Candidate(p)){var one=new CadAssembly();one.Parts.Add(p);var b=one.Bounds();if(b[1]-b[0]>256||b[3]-b[2]>256||b[5]-b[4]>256)throw new Exception(p.Label+": деталь не помещается в 256 × 256 × 256 мм.");}}s.Notes.Add("Масса = Σ V·ρ; V из геометрии, сплошное заполнение. Справочные свойства FDM зависят от марки, слоёв и режима печати; это предварительная оценка.");}
 public static void ApplyDefaults(TransmissionTrain t){t.Materials=new TrainMaterialSettings();foreach(string role in new[]{"housing","gear","shaft","bearing","fastener"})t.Materials.Roles[role]=role=="housing"||role=="gear"?"PETG":"Сталь 45";}
 public static string UserPath{get{return Path.Combine(AppSettings.Folder,"materials.json");}}
 public static void SaveUser(List<TrainMaterial> values){if(values==null||values.Count>100||values.Select(v=>v.Name).Distinct().Count()!=values.Count)throw new Exception("Личный справочник: не более 100 разных имён материалов.");foreach(var m in values)Validate(m);Directory.CreateDirectory(AppSettings.Folder);ReleaseSupport.WriteText(UserPath,CADDocument.Serializer().Serialize(values),System.Text.Encoding.UTF8);}
 public static List<TrainMaterial> LoadUser(){if(!File.Exists(UserPath))return new List<TrainMaterial>();if(new FileInfo(UserPath).Length>1024*1024)throw new Exception("Справочник материалов слишком большой.");var v=CADDocument.Serializer().Deserialize<List<TrainMaterial>>(File.ReadAllText(UserPath));if(v==null)throw new Exception("Справочник материалов пуст.");foreach(var m in v)Validate(m);return v;}
}}
